NOTA = "[FORMAZIONE_0270] copiato dalla rotta sorella"
ROTTE = {"anagrafica:formazione_allegato_delete": ("anagrafica:formazione_allegato_dispensa",)}


def avanti(apps, schema_editor):
    # Il materiale di corso già caricato (dispense, programmi) diventa leggibile dai dipendenti.
    Att = apps.get_model("anagrafica", "TrainingAttachment")
    Att.objects.filter(corso__isnull=False, tipo__in=("MATERIALE", "PROGRAMMA")).update(visibile_dipendenti=True)
    Binding = apps.get_model("core", "RoutePermissionBinding")
    for sorella, rotte in ROTTE.items():
        modello = Binding.objects.filter(route_name=sorella, is_active=True).order_by("-priority", "pk").first()
        if modello is None:
            continue
        for rotta in rotte:
            if not Binding.objects.filter(route_name=rotta).exists():
                Binding.objects.create(route_name=rotta, path_pattern="", match_strategy=modello.match_strategy,
                                       permission_id=modello.permission_id, source_app="anagrafica",
                                       priority=modello.priority, is_active=True, note=NOTA)
    # Voce di menu accanto a «I miei corsi online».
    Link = apps.get_model("anagrafica", "SubnavLinkAnagrafica")
    online = Link.objects.filter(url_value="anagrafica:formazione_online_catalog").order_by("-is_active", "id").first()
    if online is not None and not Link.objects.filter(url_value="anagrafica:dispense_libreria").exists():
        Link.objects.create(etichetta="Corsi e dispense", url_type="named", url_value="anagrafica:dispense_libreria",
                            categoria=online.categoria, gruppo=online.gruppo, ordine=online.ordine + 1,
                            icona="📚", is_sistema=True, is_active=True,
                            active_view_names="anagrafica:dispense_libreria,anagrafica:dispense_scaffale,anagrafica:dispense_corso")


def indietro(apps, schema_editor):
    rotte = [r for g in ROTTE.values() for r in g]
    apps.get_model("core", "RoutePermissionBinding").objects.filter(route_name__in=rotte, note=NOTA).delete()
    apps.get_model("anagrafica", "SubnavLinkAnagrafica").objects.filter(url_value="anagrafica:dispense_libreria").delete()



